import React from 'react'
import {Container, Row, Col} from 'react-bootstrap'
import {Link} from 'react-router-dom'
 
function Train({props}) {
    // train_number, train_name, from_sta, from_std, train_date, to_station_name
    console.log(props)
  return (
    <Link to='/train/details' style={{textDecoration: 'none', color: 'white', height: '10wh'}}>
      <Container>
        <Row>
            <Col md={2}>
                Train number : {props.train_number}
            </Col>
            <Col md={2}>
                Train name : {props.train_name}
            </Col>
            <Col md={2}>
                Date : {props.train_date}
            </Col>
            <Col md={2}>
                arrival : {props.from_sta}
            </Col>            
            <Col md={2}>
                departure : {props.from_std}
            </Col>
            <Col md={2}>
                last station : {props.to_station_name}
            </Col>
        </Row>
      </Container>
    </Link>
  )
}

export default Train
